SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- /portfolio/ (th · en · zh) lists real case studies: block `case_studies` (BlockService fills it with rows that are
-- published AND have the client's recorded permission — migration 015). No permitted case study = the block renders
-- nothing and the page keeps its honest "being collected" text.
-- Numbered 042 (not 016–019): it edits pages published by 021 and must run after it (numeric order).
-- Inserted before the last block (cta_band) · only once (skipped when the page already has the block).
-- Data change through SQL → no audit_logs rows (same as seeds 010/011/021).

-- /portfolio/ · ผลงานที่ลูกค้าอนุญาตให้เผยแพร่
UPDATE pages
   SET blocks = JSON_ARRAY_INSERT(blocks, CONCAT('$[', GREATEST(JSON_LENGTH(blocks) - 1, 0), ']'), JSON_EXTRACT(CONVERT(X'' USING utf8mb4), '$')),
       updated_at = NOW()
 WHERE path = CONVERT(X'2F706F7274666F6C696F2F' USING utf8mb4) COLLATE utf8mb4_bin AND deleted_at IS NULL
   AND JSON_SEARCH(blocks, 'one', 'case_studies', NULL, '$[*].type') IS NULL;

-- /en/portfolio/ · Client case studies
UPDATE pages
   SET blocks = JSON_ARRAY_INSERT(blocks, CONCAT('$[', GREATEST(JSON_LENGTH(blocks) - 1, 0), ']'), JSON_EXTRACT(CONVERT(X'' USING utf8mb4), '$')),
       updated_at = NOW()
 WHERE path = CONVERT(X'2F656E2F706F7274666F6C696F2F' USING utf8mb4) COLLATE utf8mb4_bin AND deleted_at IS NULL
   AND JSON_SEARCH(blocks, 'one', 'case_studies', NULL, '$[*].type') IS NULL;

-- /zh/portfolio/ · 客户案例
UPDATE pages
   SET blocks = JSON_ARRAY_INSERT(blocks, CONCAT('$[', GREATEST(JSON_LENGTH(blocks) - 1, 0), ']'), JSON_EXTRACT(CONVERT(X'7B2274797065223A22636173655F73747564696573222C2264617461223A7B227469746C65223A22E5AEA2E688B7E6A188E4BE8B222C226C656164223A224F4D4320E4B8BAE5AEA2E688B7E5BC80E58F91E79A84E7B3BBE7BB9F20E2809420E4BB85E5B195E7A4BAE5B7B2E88EB7E5AEA2E688B7E8AEB8E58FAFE79A84E6A188E4BE8B227D7D' USING utf8mb4), '$')),
       updated_at = NOW()
 WHERE path = CONVERT(X'2F7A682F706F7274666F6C696F2F' USING utf8mb4) COLLATE utf8mb4_bin AND deleted_at IS NULL
   AND JSON_SEARCH(blocks, 'one', 'case_studies', NULL, '$[*].type') IS NULL;
